// ==========================================
// UTILIDADES
// ==========================================
function sumarMinutos(fechaStr, minutos) {
  const fecha = new Date(fechaStr);
  if (isNaN(fecha)) throw new Error(`Fecha inválida: ${fechaStr}`);
  fecha.setMinutes(fecha.getMinutes() + minutos);
  const [fechaPart, horaPart] = fecha.toISOString().split("T");
  return `${fechaPart}T${horaPart.substring(0, 5)}:00`;
}

function tiempoAHorasMinutos(tiempoStr) {
  if (!tiempoStr || typeof tiempoStr !== "string") return 30;
  const partes = tiempoStr.split(":").map(Number);
  if (partes.length === 3) {
    const [h, m, s] = partes;
    return h * 60 + m + (s > 0 ? Math.round(s / 60) : 0);
  }
  if (partes.length === 2) {
    const [h, m] = partes;
    return h * 60 + m;
  }
  return parseInt(tiempoStr) || 30;
}

// ==========================================
// NORMALIZAR OBJETO
// ==========================================
function normalizar(obj) {
  if (!obj || typeof obj !== "object") return {};
  const flat = {};
  for (const [k, v] of Object.entries(obj)) {
    flat[k.toLowerCase()] = v;
  }
  return {
    fecha:         flat.fecha         || null,
    hora_llegada:  flat.hora_llegada  || null,
    hora_entrega:  flat.hora_entrega  || null,
    patente:       flat.patente       || null,
    modelo:        flat.modelo        || null,
    nombre:        flat.nombre        || null,
    telefono:      flat.telefono      || null,
    email:         flat.email         || null,
    vin:           flat.vin           || flat.chasis || null,
    km:            flat.km            ?? null,
    precio:        flat.precio        ?? null,
    descripcion:   flat.descripcion   || null,
    id_calendario: flat.id_calendario || null,
  };
}

// ==========================================
// EXTRAER INPUT
// ==========================================
function extraerSolicitud() {
  try {
    return normalizar($('When Executed by Another Workflow').first().json);
  } catch (e) {
    const raw = $("Execute Workflow Trigger").all();
    const first = Array.isArray(raw) ? raw[0] : raw;
    const base = first?.json ?? first;
    let parsed;
    if (base?.query) {
      parsed = typeof base.query === "string" ? JSON.parse(base.query) : base.query;
    } else {
      parsed = base;
    }
    return normalizar(parsed);
  }
}

// ==========================================
// NORMALIZAR MODELO
// ==========================================
const MODELOS = [
  "Etios", "Yaris", "Yaris GR", "Corolla", "Prius", "Rav4",
  "Innova", "Hilux", "SW4", "Hiace", "CH-R", "Camry", "Land Cruiser"
];

function normalizarModelo(modeloRaw) {
  if (!modeloRaw) return null;
  const limpio = modeloRaw.toString().trim().toLowerCase();
  const match = MODELOS.find(m => limpio.includes(m.toLowerCase()));
  return match || null;
}

function normalizarMapa(obj) {
  const map = {};
  Object.keys(obj || {}).forEach(k => {
    map[k.toLowerCase()] = obj[k];
  });
  return map;
}

// ==========================================
// VALIDAR CONFLICTO CON TURNOS OCUPADOS
// ==========================================
function hayConflicto(nuevoInicio, nuevoFin, turnosOcupados) {
  const inicio = new Date(nuevoInicio).getTime();
  const fin    = new Date(nuevoFin).getTime();

  for (const item of turnosOcupados) {
    const dia = item.json;
    if (!dia?.occupiedRanges) continue;

    const fechaNuevo = nuevoInicio.split("T")[0];
    if (dia.date !== fechaNuevo) continue;

    for (const rango of dia.occupiedRanges) {
      // Convertir "HH:MM" a timestamp del mismo día
      const rangoInicio = new Date(`${fechaNuevo}T${rango.from}:00`).getTime();
      const rangoFin    = new Date(`${fechaNuevo}T${rango.to}:00`).getTime();

      // Overlap: nuevo empieza antes de que termine el ocupado
      //          y termina después de que empiece el ocupado
      if (inicio < rangoFin && fin > rangoInicio) {
        return {
          conflicto: true,
          turnoExistente: rango
        };
      }
    }
  }

  return { conflicto: false };
}

// ==========================================
// OBTENER DATOS
// ==========================================
const solicitud = extraerSolicitud();

const modelo = normalizarModelo(
  $("Code4").first()?.json?.modelo ||
  $("Code4").first()?.json?.Modelo ||
  solicitud.modelo
);

const tiemposRaw = $("Get_Tiempo").first()?.json || {};
const tiempos = Array.isArray(tiemposRaw) ? tiemposRaw[0] : tiemposRaw;
const tiemposMap = normalizarMapa(tiempos);

const reglasRaw = $("Get_Reglas").first()?.json || {};
const reglas = Array.isArray(reglasRaw) ? reglasRaw[0] : reglasRaw;

const turnosOcupados = $("turnos_ocupados").all();

// ==========================================
// CONSTRUIR FECHAS
// ==========================================
let Fecha = solicitud.fecha;
let Fin   = null;

if (Fecha && !Fecha.includes("T") && solicitud.hora_llegada) {
  Fecha = `${Fecha}T${solicitud.hora_llegada}:00`;
}

if (Fecha && solicitud.hora_entrega) {
  Fin = `${Fecha.split("T")[0]}T${solicitud.hora_entrega}:00`;
}

if (!Fecha || !Fin) {
  return [{
    json: {
      error: "Faltan campos requeridos (Fecha o Fin)",
      debug: { solicitud, Fecha, Fin }
    }
  }];
}

// ==========================================
// CALCULAR TIEMPOS
// ==========================================
let tiempoModeloStr = null;

if (modelo) {
  tiempoModeloStr = tiemposMap[modelo.toLowerCase()];
}

const minutosModelo    = tiempoAHorasMinutos(tiempoModeloStr);
const minutosRecepcion = parseInt(reglas?.Recepcion || reglas?.recepcion) || 15;

const nuevaFechaInicio = sumarMinutos(Fecha, minutosRecepcion);
const nuevoFin         = sumarMinutos(nuevaFechaInicio, minutosModelo);

// ==========================================
// VALIDAR CONFLICTO
// ==========================================
const { conflicto, turnoExistente } = hayConflicto(nuevaFechaInicio, nuevoFin, turnosOcupados);

if (conflicto) {
  return [{
    json: {
      error: "Turno en conflicto con uno ya existente",
      turno_solicitado: {
        inicio: nuevaFechaInicio,
        fin:    nuevoFin
      },
      turno_existente: turnoExistente
    }
  }];
}

// ==========================================
// OUTPUT
// ==========================================
const titulo = `Servicio ${modelo || "Sin modelo"} - ${solicitud.nombre || "Cliente desconocido"} (${solicitud.patente || "Sin patente"})`;

return [{
  json: {
    Fecha:             nuevaFechaInicio,
    Fin:               nuevoFin,
    Modelo:            modelo || "Desconocido",
    Nombre:            solicitud.nombre,
    Patente:           solicitud.patente,
    Telefono:          solicitud.telefono,
    Email:             solicitud.email,
    Vin:               solicitud.vin,
    Km:                solicitud.km,
    Precio:            solicitud.precio,
    Descripcion:       solicitud.descripcion,
    Titulo:            titulo,
    Calendar:          solicitud.id_calendario || reglas?.Id_Calendario || reglas?.id_calendario,
    Tiempo_Modelo:     tiempoModeloStr || "fallback 30",
    Fallback_Aplicado: !tiempoModeloStr,
  }
}];

const MODELOS = [
  "Etios", "Yaris", "Yaris GR", "Corolla", "Prius", "Rav4",
  "Innova", "Hilux", "SW4", "Hiace", "CH-R", "Camry", "Land Cruiser"
];

const KM_VALIDOS = [
  1000, 10000, 20000, 30000, 40000, 50000, 60000,
  70000, 80000, 90000, 100000, 110000, 120000,
  130000, 140000, 150000, 160000, 170000,
  180000, 190000, 200000
];

// ==========================================
// HELPERS
// ==========================================

// case insensitive
function get(obj, key) {
  if (!obj) return undefined;
  const lower = key.toLowerCase();
  const found = Object.keys(obj).find(k => k.toLowerCase() === lower);
  return found ? obj[found] : undefined;
}

// normalizar modelo (PRO)
function normalizarModelo(modeloRaw, texto = "") {
  if (modeloRaw) {
    const limpio = modeloRaw.toString().trim().toLowerCase();

    const match = MODELOS.find(m =>
      limpio.includes(m.toLowerCase())
    );

    if (match) return match;
  }

  // fallback: buscar en texto
  for (const modelo of MODELOS) {
    if (new RegExp(`\\b${modelo}\\b`, "i").test(texto)) {
      return modelo;
    }
  }

  return null;
}

// detectar KM desde texto
function detectarKilometrajeTexto(texto) {
  const match = texto.match(/(\d{1,3}(?:\.\d{3})*|\d+)\s*km/i);
  if (match) return parseInt(match[1].replace(/\./g, ""), 10);
  return null;
}

// normalizar KM al más cercano
function normalizarKm(km) {
  if (km === null || km === undefined) return null;

  const kmNum = parseInt(km);
  if (isNaN(kmNum)) return null;

  let masCercano = KM_VALIDOS[0];
  let menorDiferencia = Math.abs(kmNum - masCercano);

  for (const valor of KM_VALIDOS) {
    const diferencia = Math.abs(kmNum - valor);
    if (diferencia < menorDiferencia) {
      menorDiferencia = diferencia;
      masCercano = valor;
    }
  }

  return masCercano;
}

// detectar si viene de workflow o texto
function esWorkflowDirecto(obj) {
  return obj && (obj.KM !== undefined || obj.Modelo !== undefined);
}

// ==========================================
// INPUT
// ==========================================

let input;

// intenta workflow directo
try {
  input = $('When Executed by Another Workflow').first().json;
} catch (e) {
  // fallback: input tipo IA
  const raw = $("Execute Workflow Trigger").all();
  const first = Array.isArray(raw) ? raw[0] : raw;
  const base = first?.json ?? first;

  if (base?.query) {
    input = typeof base.query === "string" ? JSON.parse(base.query) : base.query;
  } else {
    input = base;
  }
}

// ==========================================
// PROCESAMIENTO
// ==========================================

let modelo = null;
let kmOriginal = null;

// 🔥 PRIORIDAD: datos estructurados
if (esWorkflowDirecto(input)) {
  modelo = normalizarModelo(get(input, "Modelo"));
  kmOriginal = parseInt(get(input, "KM"));
} else {
  const texto = `${get(input, "descripcion") || ""} ${get(input, "titulo") || ""}`.trim();

  modelo = normalizarModelo(get(input, "modelo"), texto);
  kmOriginal =
    get(input, "km") ??
    get(input, "kilometraje") ??
    detectarKilometrajeTexto(texto);
}

// normalizar KM final
const kmNormalizado = normalizarKm(kmOriginal);

// ==========================================
// OUTPUT
// ==========================================

return [{
  json: {
    modelo,
    kilometraje: kmNormalizado,
    kilometraje_original: kmOriginal,

    // 🔹 passthrough completo (clave en producción)
    ...input
  }
}];

const items = $input.all();

const occupiedByDay = {};

for (const item of items) {
  const event = item.json;

  const startDT = new Date(event.start.dateTime);
  const endDT = new Date(event.end.dateTime);

  const dateKey = startDT.toLocaleDateString('sv-SE', {
    timeZone: 'America/Argentina/Buenos_Aires'
  });

  const startStr = startDT.toLocaleTimeString('es-AR', {
    timeZone: 'America/Argentina/Buenos_Aires',
    hour: '2-digit',
    minute: '2-digit',
    hour12: false
  });

  const endStr = endDT.toLocaleTimeString('es-AR', {
    timeZone: 'America/Argentina/Buenos_Aires',
    hour: '2-digit',
    minute: '2-digit',
    hour12: false
  });

  if (!occupiedByDay[dateKey]) {
    occupiedByDay[dateKey] = {
      date: dateKey,
      dayOfWeek: startDT.toLocaleDateString('es-AR', {
        timeZone: 'America/Argentina/Buenos_Aires',
        weekday: 'long'
      }),
      occupiedRanges: []
    };
  }

  occupiedByDay[dateKey].occupiedRanges.push({
    from: startStr,
    to: endStr,
    summary: event.summary || 'Sin título'
  });
}

// Ordenar por fecha y franjas por hora de inicio
const result = Object.values(occupiedByDay)
  .sort((a, b) => a.date.localeCompare(b.date))
  .map(day => ({
    ...day,
    occupiedRanges: day.occupiedRanges.sort((a, b) => a.from.localeCompare(b.from))
  }));

return result.map(day => ({ json: day }));

const item = $input.first().json;

const [year, month, day] = item.fecha.split('-');
const fecha = `${day}/${month}/${year}`;

const precioFormateado = parseInt(item.precio).toLocaleString('es-AR');

const ahora = new Date();
const fechaAgendamiento = ahora.toLocaleDateString('es-AR', { day: '2-digit', month: '2-digit', year: 'numeric' });
const horaAgendamiento = ahora.toLocaleTimeString('es-AR', { hour: '2-digit', minute: '2-digit' });

const mail = [
  `✅ NUEVO TURNO AGENDADO`,
  `⏰ FECHA Y HORA DE AGENDAMIENTO: ${fechaAgendamiento} ${horaAgendamiento}`,
  `📋 INFORMACIÓN DEL TURNO:`,
  `─────────────────────────────────────────────────`,
  `📅 Fecha: ${fecha}`,
  `🕐 Horario de llegada: ${item.hora_llegada}`,
  `🕐 Horario de entrega: ${item.hora_entrega}`,
  `🏢 Bahía: Express`,
  `🔧 Servicio: Mantenimiento con ${item.KM} km`,
  `👤 DATOS DEL CLIENTE:`,
  `─────────────────────────────────────────────────`,
  `Nombre: ${item.nombre.toUpperCase()}`,
  `Teléfono: ${item.telefono}`,
  `Email: ${item.email}`,
  `🚗 DATOS DEL VEHÍCULO:`,
  `─────────────────────────────────────────────────`,
  `Patente: ${item.patente}`,
  `Modelo: ${item.Modelo}`,
  `Kilometraje: ${item.KM}`,
  `Chasis/VIN: ${item.chasis}`,
  `💰 PRECIO INFORMADO: $${precioFormateado}`
].join('\n');
const titulo = `✅ NUEVO TURNO AGENDADO - Patente ${item.patente}`;
return [{ json: { mail, titulo } }];
